using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class AnnouncementsPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Announcements", "View"); return AdminDataService.GetList("Announcements"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Announcements", "View"); return AdminDataService.GetDefinitionMetadata("Announcements"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Announcements", "Delete"); return AdminDataService.Delete("Announcements", id); } } }
